      + '<div class="between"><span style="font-size:15px;font-weight:700">'+esc(p.merchant)+'</span>'
      + '<span style="font-size:15px;font-weight:700">'+money(p.total)+'</span></div>'
      + '<div class="between" style="margin-top:5px">'
      + '<span class="micro">'+esc(p.cat)+' &middot; '+p.count+' purchases this week</span>'
      + '<span class="micro">avg '+money(p.total/p.count)+'</span></div>'
      + '</button>';
